int analyzeSemantics(
    SemanticContext *context,
    const SyntaxNode *root)
{
    if (context->memoryError || !isNode(root, "CompUnit"))
    {
        return 0;
    }

    // 第一次进入作用域，创建编号为 1 的全局作用域。
